                    "sql": "Create or replace table maplemonk.s3_SKU_Level_Consolidated as SELECT cast(NULL as string) AS customer_id ,CHANNEL AS shop_name ,CHANNEL AS marketplace ,CHANNEL AS CHANNEL ,CHANNEL AS SOURCE ,concat(FSIN, Date) ORDER_ID ,concat(FSIN, Date) reference_code ,cast(NULL as string) AS PHONE ,cast(NULL as string) AS NAME ,cast(NULL as string) AS EMAIL ,cast(date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,FSIN as SKU ,FSIN as PRODUCT_ID ,cast(NULL as string) AS PRODUCT_NAME ,\'IN\' CURRENCY ,cast(NULL as string) AS city ,cast(NULL as string) AS State ,cast(\'\' as string) AS order_status ,date AS Order_Date ,date ORDER_TIME ,cast(Quantity AS FLOAT64) AS QUANTITY ,cast(Selling_Price as float64) AS gross_sales_before_tax ,cast(0 as float64) AS DISCOUNT ,cast(0 as float64) TAX ,cast(0 as float64) as SHIPPING_PRICE ,cast(Selling_Price as float64) as SELLING_PRICE ,cast(NULL as string) AS OMS_ORDER_STATUS ,cast(\'\' as string) SHIPPING_STATUS ,cast(\'\' as string) AS FINAL_SHIPPING_STATUS ,concat(FSIN, date) AS SALEORDERITEMCODE ,concat(FSIN, date) AS SALES_ORDER_ITEM_ID ,cast(null as string) AWB ,cast(NULL as string) AS payment_gateway ,cast(NULL as string) as payment_mode ,cast(NULL as string) COURIER ,cast(NULL as date) AS DISPATCH_DATE ,cast(NULL as date) AS delivered_date ,cast(NULL as int64) DELIVERED_STATUS ,cast(NULL as int64) AS RETURN_FLAG ,cast(NULL as int64) as returned_quantity ,cast(NULL as int64) as returned_sales ,cast(NULL as int64) as cancelled_quantity , cast(NULL as string) AS NEW_CUSTOMER_FLAG ,cast(NULL as string) AS ACQUISITION_PRODUCT ,0 as days_in_shipment ,cast(NULL as date) AS ACQUISITION_DATE ,FSIN as sku_code ,name AS PRODUCT_NAME_FINAL ,p.category AS PRODUCT_CATEGORY ,p.sub_category AS PRODUCT_SUB_CATEGORY ,collection as COLLECTION ,print as PRINT ,PRODUCT_TYPE as PRODUCT_TYPE ,category_code category_code ,BAU_OFFLINE BAU_OFFLINE ,BAU_ONLINE BAU_ONLINE ,TAX_RATE as FINAL_TAX_RATE ,commonsku ,cast(NULL as string) AS warehouse ,cast(NULL as string) as pincode ,cast(NULL as string) source_pincode ,FINAL_MARKETPLACE ,Marketplace_Segments ,TYPE_OF_SALE from ( select trim(sku) AS FSIN, COALESCE( SAFE.PARSE_DATE(\'%d %B %Y\', Date), SAFE.PARSE_DATE(\'%d-%b-%y\', Date), SAFE.PARSE_DATE(\'%Y-%m-%d\', Date) ) AS Date, trim(upper(Channel)) channel, sum(ifnull(safe_cast(replace(CAST(Revenue AS STRING),\',\',\'\') AS FLOAT64),0)) Selling_Price, sum(ifnull(safe_cast(replace(CAST(Quantity AS STRING),\',\',\'\') AS FLOAT64),0)) Quantity from maplemonk.s3_new_zouk_seondary_sales group by 1,2,3 ) fi left join (select * from (select marketplace_sku skucode, name, category, sub_category, category_code, collection, print, PRODUCT_TYPE, commonsku, BAU_OFFLINE, BAU_ONLINE, TAX_RATE , row_number()over (partition by marketplace_sku order by 1) rw from zouk-wh.maplemonk.final_sku_master ) where rw = 1 ) p on lower(fi.FSIN) = lower(p.skucode) LEFT JOIN (select * from (Select * , row_number() over (partition by lower(marketplace) order by 1) rw from maplemonk.marketplace_mapping ) where rw =1 ) mm ON lower(fi.channel) = lower(mm.marketplace) ; Create or replace table maplemonk.s3_consolidated as SELECT \'\' AS customer_id ,UPPER(marketplace) AS shop_name ,UPPER(marketplace) AS marketplace ,UPPER(marketplace) AS CHANNEL ,UPPER(marketplace) AS SOURCE ,ORDER_ID ,reference_code ,phone AS PHONE ,name AS NAME ,email AS EMAIL ,cast(shipping_last_update_date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,SKU ,b.PRODUCT_ID ,PRODUCT_NAME AS PRODUCT_NAME ,CURRENCY ,UPPER(CITY) AS city ,UPPER(STATE) AS State ,UPPER(ORDER_STATUS) AS order_status ,CAST(ORDER_DATE AS DATE) AS Order_Date ,CAST(ORDER_DATE AS datetime) ORDER_TIME ,SUBORDER_QUANTITY AS QUANTITY ,IFNULL(SELLING_PRICE, 0) - IFNULL(tax, 0) AS gross_sales_before_tax ,DISCOUNT AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,UPPER(ORDER_STATUS) AS OMS_ORDER_STATUS ,UPPER(b.shipping_status) AS SHIPPING_STATUS ,UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS ,saleOrderItemCode AS SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID AS SALES_ORDER_ITEM_ID ,cast(AWB as string) as AWB ,NULL AS payment_gateway ,payment_mode ,COURIER ,DISPATCH_DATE AS DISPATCH_DATE ,delivered_date AS delivered_date ,CASE WHEN UPPER(FINAL_SHIPPING_STATUS) IN (\'DELIVERED\') THEN 1 END AS DELIVERED_STATUS ,return_flag AS RETURN_FLAG ,CASE WHEN return_flag = 1 THEN CAST(suborder_quantity AS INT64) END AS returned_quantity ,CASE WHEN return_flag = 1 THEN CAST(selling_price AS FLOAT64) END AS returned_sales ,CASE WHEN return_flag = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS INT64) END AS cancelled_quantity ,CAST(new_customer_flag AS STRING) AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,CASE WHEN order_status = \'COMPLETE\' THEN date_diff(CAST(delivered_date AS DATE), CAST(order_date AS DATE),day) ELSE date_diff(CURRENT_DATE(), CAST(order_date AS DATE),day) END AS days_in_shipment ,NULL AS ACQUISITION_DATE ,sku_code ,UPPER(b.product_name_final) AS PRODUCT_NAME_FINAL ,UPPER(b.Product_Category) AS PRODUCT_CATEGORY ,UPPER(b.product_sub_category) AS PRODUCT_SUB_CATEGORY ,b.COLLECTION ,b.PRINT ,b.PRODUCT_TYPE ,b.category_code ,b.BAU_OFFLINE ,b.BAU_ONLINE ,b.FINAL_TAX_RATE ,b.commonsku ,UPPER(warehouse_name) AS warehouse ,b.pincode ,fa.pincode source_pincode ,b.FINAL_MARKETPLACE ,b.MARKETPLACE_SEGMENT ,b.TYPE_OF_SALE FROM maplemonk.zouk_unicommerce_fact_items b left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from maplemonk.facility_pincode ) where rw = 1 ) fa on lower(b.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM maplemonk.shipment_status_mapping ) ShipMap WHERE ShipMap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) WHERE LOWER(b.marketplace) like \'%blinkit%\' and not(LOWER(TYPE_OF_SALE) LIKE ANY (\'na\',\'%stock%\')) UNION ALL SELECT NULL AS customer_id ,\'SWIGGY_INSTAMART\' AS shop_name ,\'SWIGGY_INSTAMART\' AS marketplace ,\'SWIGGY_INSTAMART\' AS CHANNEL ,\'SWIGGY_INSTAMART\' AS SOURCE ,concat(ITEM_CODE, ORDERED_DATE,store_id) ORDER_ID ,concat(ITEM_CODE, ORDERED_DATE,store_id) reference_code ,null AS PHONE ,null AS NAME ,null AS EMAIL ,cast(cast(PARSE_DATE(\'%d-%m-%Y\', ORDERED_DATE) as date) as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,ITEM_CODE as SKU ,ITEM_CODE as PRODUCT_ID ,PRODUCT_NAME AS PRODUCT_NAME ,\'IN\' CURRENCY ,CITY AS city ,NULL AS State ,NUll AS order_status ,cast(PARSE_DATE(\'%d-%m-%Y\', ORDERED_DATE) as date) AS Order_Date ,CAST(cast(PARSE_DATE(\'%d-%m-%Y\', ORDERED_DATE) as date) as datetime) ORDER_TIME ,cast(UNITS_SOLD AS FLOAT64) AS QUANTITY ,cast(BAU_ONLINE as float64)* cast(UNITS_SOLD AS int64) AS gross_sales_before_tax ,cast(0 as float64) AS DISCOUNT ,cast(0 as float64) TAX ,cast(0 as float64) as SHIPPING_PRICE ,cast(BAU_ONLINE as float64)*cast(UNITS_SOLD AS INT64) as SELLING_PRICE ,null AS OMS_ORDER_STATUS ,null SHIPPING_STATUS ,null AS FINAL_SHIPPING_STATUS ,concat(ITEM_CODE, ORDERED_DATE) AS SALEORDERITEMCODE ,concat(ITEM_CODE, ORDERED_DATE) AS SALES_ORDER_ITEM_ID ,cast(null as string) AWB ,NULL AS payment_gateway ,null as payment_mode ,null COURIER ,null AS DISPATCH_DATE ,null AS delivered_date ,null DELIVERED_STATUS , null AS RETURN_FLAG ,null as returned_quantity ,null as returned_sales ,null as cancelled_quantity ,null AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,null as days_in_shipment ,NULL AS ACQUISITION_DATE ,ITEM_CODE as sku_code ,name AS PRODUCT_NAME_FINAL ,category AS PRODUCT_CATEGORY ,p.sub_category AS PRODUCT_SUB_CATEGORY ,collection as COLLECTION ,print as PRINT ,PRODUCT_TYPE as PRODUCT_TYPE ,category_code category_code ,BAU_OFFLINE BAU_OFFLINE ,BAU_ONLINE BAU_ONLINE ,TAX_RATE as FINAL_TAX_RATE ,commonsku ,null AS warehouse ,null as pincode ,null source_pincode ,\'SWIGGY_INSTAMART\' FINAL_MARKETPLACE ,\'QUICK-COMMERCE\' MARKETPLACE_SEGMENT ,\'SWIGGY_INSTAMART\' TYPE_OF_SALE from (select *, row_number() over(partition by concat(ITEM_CODE, ORDERED_DATE,store_id) order by 1) rw from maplemonk.zouk_db_zouk_swiggy_instamart_orders ) fi left join (select * from (select marketplace_sku skucode, name, category, sub_category, category_code, collection, print, PRODUCT_TYPE, commonsku, BAU_OFFLINE, BAU_ONLINE, TAX_RATE , row_number()over (partition by marketplace_sku order by 1) rw from zouk-wh.maplemonk.final_sku_master where lower(marketplace) like \'%swiggy%\') where rw = 1 ) p on lower(fi.ITEM_CODE) = lower(p.skucode) where fi.rw = 1 union all SELECT NULL AS customer_id ,\'FLIPKART_SOR\' AS shop_name ,\'FLIPKART_SOR\' AS marketplace ,\'FLIPKART_SOR\' AS CHANNEL ,\'FLIPKART_SOR\' AS SOURCE ,concat(FSIN, Date) ORDER_ID ,concat(FSIN, Date) reference_code ,null AS PHONE ,null AS NAME ,null AS EMAIL ,cast(COALESCE(SAFE.PARSE_DATE(\'%d-%b-%Y\', Date),SAFE.PARSE_DATE(\'%d/%b/%Y\', Date)) as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,FSIN as SKU ,FSIN as PRODUCT_ID ,NULL AS PRODUCT_NAME ,\'IN\' CURRENCY ,NULL AS city ,NULL AS State ,NUll AS order_status ,cast(COALESCE(SAFE.PARSE_DATE(\'%d-%b-%Y\', Date),SAFE.PARSE_DATE(\'%d/%b/%Y\', Date)) as date) AS Order_Date ,CAST(COALESCE(SAFE.PARSE_DATE(\'%d-%b-%Y\', Date),SAFE.PARSE_DATE(\'%d/%b/%Y\', Date)) as datetime) ORDER_TIME ,cast(Quantity AS FLOAT64) AS QUANTITY ,cast(Selling_Price as float64) AS gross_sales_before_tax ,cast(0 as float64) AS DISCOUNT ,cast(0 as float64) TAX ,cast(0 as float64) as SHIPPING_PRICE ,cast(Selling_Price as float64) as SELLING_PRICE ,null AS OMS_ORDER_STATUS ,null SHIPPING_STATUS ,null AS FINAL_SHIPPING_STATUS ,concat(FSIN, date) AS SALEORDERITEMCODE ,concat(FSIN, date) AS SALES_ORDER_ITEM_ID ,cast(null as string) AWB ,NULL AS payment_gateway ,null as payment_mode ,null COURIER ,null AS DISPATCH_DATE ,null AS delivered_date ,null DELIVERED_STATUS , null AS RETURN_FLAG ,null as returned_quantity ,null as returned_sales ,null as cancelled_quantity ,null AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,null as days_in_shipment ,NULL AS ACQUISITION_DATE ,FSIN as sku_code ,name AS PRODUCT_NAME_FINAL ,category AS PRODUCT_CATEGORY ,p.sub_category AS PRODUCT_SUB_CATEGORY ,collection as COLLECTION ,print as PRINT ,PRODUCT_TYPE as PRODUCT_TYPE ,category_code category_code ,BAU_OFFLINE BAU_OFFLINE ,BAU_ONLINE BAU_ONLINE ,TAX_RATE as FINAL_TAX_RATE ,commonsku ,null AS warehouse ,null as pincode ,null source_pincode ,\'FLIPKART_SOR\' FINAL_MARKETPLACE ,\'E-COMMERCE\' MARKETPLACE_SEGMENT ,\'SALES\' TYPE_OF_SALE from maplemonk.zouk_db_s3_flipkart_sor fi left join (select * from (select marketplace_sku skucode, name, category, sub_category, category_code, collection, print, PRODUCT_TYPE, commonsku, BAU_OFFLINE, BAU_ONLINE, TAX_RATE , row_number()over (partition by marketplace_sku order by 1) rw from zouk-wh.maplemonk.final_sku_master where lower(marketplace) like \'%flipkart%\') where rw = 1 ) p on lower(fi.FSIN) = lower(p.skucode) UNION ALL SELECT NULL AS customer_id ,\'MYNTRA_SOR\' AS shop_name ,\'MYNTRA_SOR\' AS marketplace ,\'MYNTRA_SOR\' AS CHANNEL ,\'MYNTRA_SOR\' AS SOURCE ,CONCAT(sku_code, CAST(date AS STRING)) ORDER_ID ,CONCAT(sku_code, CAST(date AS STRING)) reference_code ,null AS PHONE ,null AS NAME ,null AS EMAIL ,cast(PARSE_DATE(\'%m/%d/%Y\', Date) as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,sku_id as SKU ,style_id PRODUCT_ID ,null AS PRODUCT_NAME ,\'IN\' CURRENCY ,NULL AS city ,NULL AS State ,NUll AS order_status ,PARSE_DATE(\'%m/%d/%Y\', Date) AS Order_Date ,CAST(PARSE_DATE(\'%m/%d/%Y\', Date) as datetime) ORDER_TIME ,cast(sold_quantity as float64) AS QUANTITY ,cast(0 as float64) AS gross_sales_before_tax ,cast(0 as float64) AS DISCOUNT ,cast(0 as float64) TAX ,cast(0 as float64) as SHIPPING_PRICE ,cast(0 as float64) as SELLING_PRICE ,null AS OMS_ORDER_STATUS ,null SHIPPING_STATUS ,null AS FINAL_SHIPPING_STATUS ,cast(concat(sku_code,date) as string) AS SALEORDERITEMCODE ,cast(concat(sku_code,date) as string) AS SALES_ORDER_ITEM_ID ,cast(null as string) AWB ,NULL AS payment_gateway ,null as payment_mode ,null COURIER ,null AS DISPATCH_DATE ,null AS delivered_date ,null DELIVERED_STATUS , null AS RETURN_FLAG ,null as returned_quantity ,null as returned_sales ,null as cancelled_quantity ,null AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,null as days_in_shipment ,NULL AS ACQUISITION_DATE ,sku_code as sku_code ,name AS PRODUCT_NAME_FINAL ,category AS PRODUCT_CATEGORY ,p.sub_category AS PRODUCT_SUB_CATEGORY ,collection as COLLECTION ,print as PRINT ,PRODUCT_TYPE as PRODUCT_TYPE ,category_code category_code ,BAU_OFFLINE BAU_OFFLINE ,BAU_ONLINE BAU_ONLINE ,TAX_RATE as FINAL_TAX_RATE ,commonsku ,null AS warehouse ,null as pincode ,null source_pincode ,\'MYNTRA\' FINAL_MARKETPLACE ,\'E-COMMERCE\' MARKETPLACE_SEGMENT ,\'SALES\' TYPE_OF_SALE from maplemonk.zouk_myntra_sor_orders fi left join (select * from (select marketplace_sku skucode, name, category, sub_category, category_code, collection, print, PRODUCT_TYPE, commonsku, BAU_OFFLINE, BAU_ONLINE, TAX_RATE , row_number()over (partition by marketplace_sku order by 1) rw from zouk-wh.maplemonk.final_sku_master where lower(marketplace) like \'%myntra%\') where rw = 1 ) p on lower(fi.sku_code) = lower(p.skucode) UNION ALL SELECT NULL AS customer_id ,\'FLIPKART_FBF\' AS shop_name ,\'FLIPKART_FBF\' AS marketplace ,\'FLIPKART_FBF\' AS CHANNEL ,\'FLIPKART_FBF\' AS SOURCE ,cast(Product_Id as string) ORDER_ID ,cast(Product_Id as string) reference_code ,null AS PHONE ,null AS NAME ,null AS EMAIL ,cast(Order_Date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,sku_id as SKU ,Product_Id PRODUCT_ID ,name AS PRODUCT_NAME ,\'IN\' CURRENCY ,null AS city ,null AS State ,null AS order_status ,CAST(date(Order_Date) AS DATE) AS Order_Date ,CAST(date(Order_Date) AS datetime) ORDER_TIME ,cast(Gross_Units as int64) AS QUANTITY ,IFNULL(cast(Final_Sale_Amount as int64),0) - IFNULL(cast(0 as int64), 0) AS gross_sales_before_tax ,cast(0 as float64) AS DISCOUNT ,cast(0 as float64) TAX ,cast(0 as float64) as SHIPPING_PRICE ,cast(Final_Sale_Amount as float64) AS SELLING_PRICE ,null AS OMS_ORDER_STATUS ,null as SHIPPING_STATUS ,null AS FINAL_SHIPPING_STATUS ,Product_Id AS SALEORDERITEMCODE ,Product_Id AS SALES_ORDER_ITEM_ID ,cast(null as string) AWB ,NULL AS payment_gateway ,null as payment_mode ,null COURIER ,null AS DISPATCH_DATE ,null AS delivered_date ,null as DELIVERED_STATUS , case when CAST(Return_Units AS INT64) > 0 then 1 else 0 end AS RETURN_FLAG ,CAST(Return_Units AS INT64) returned_quantity ,CAST(Return_Amount AS FLOAT64) AS returned_sales ,CAST(Cancellation_Units AS INT64) cancelled_quantity ,null AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,null days_in_shipment ,NULL AS ACQUISITION_DATE ,sku_id as sku_code ,name AS PRODUCT_NAME_FINAL ,p.category AS PRODUCT_CATEGORY ,sub_category AS PRODUCT_SUB_CATEGORY ,collection as COLLECTION ,print as PRINT ,PRODUCT_TYPE as PRODUCT_TYPE ,category_code category_code ,BAU_OFFLINE BAU_OFFLINE ,BAU_ONLINE BAU_ONLINE ,TAX_RATE as FINAL_TAX_RATE ,commonsku ,UPPER(Location_Id) AS warehouse ,null as pincode ,null source_pincode ,\'FLIPKART\' FINAL_MARKETPLACE ,\'E-COMMERCE\' MARKETPLACE_SEGMENT ,\'SALES\' TYPE_OF_SALE from maplemonk.zouk_flipkart_fbf_orders fi left join (select * from (select marketplace_sku skucode, name, category, sub_category, category_code, collection, print, PRODUCT_TYPE, commonsku, BAU_OFFLINE, BAU_ONLINE, TAX_RATE , row_number()over (partition by marketplace_sku order by 1) rw from zouk-wh.maplemonk.final_sku_master where lower(marketplace) like \'%flipkart%\') where rw = 1 ) p on lower(fi.sku_id) = lower(p.skucode) ; create or replace table maplemonk.zouk_Secondary_sales_consolidated_intermediate as select b.customer_id ,upper(b.SHOP_NAME) SHOP_NAME ,upper(b.marketplace) as marketplace ,Upper(b.FINAL_UTM_CHANNEL) AS CHANNEL ,Upper(coalesce(b.source,b.FINAL_UTM_SOURCE)) AS SOURCE ,b.ORDER_ID ,order_name reference_code ,b.PHONE ,b.NAME ,b.EMAIL ,coalesce(cast(b.shipping_status_update_date as timestamp),cast(c.shipping_last_update_date as timestamp), cast(d.shipping_last_update_date as timestamp)) AS SHIPPING_LAST_UPDATE_DATE ,b.SKU ,b.PRODUCT_ID ,Upper(b.PRODUCT_NAME) PRODUCT_NAME ,b.CURRENCY ,Upper(b.CITY) As CITY ,Upper(b.STATE) AS State ,Upper(b.ORDER_STATUS) ORDER_STATUS ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as date) AS Order_Date ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as datetime) AS Order_Time ,b.QUANTITY ,b.GROSS_SALES_BEFORE_TAX AS GROSS_SALES_BEFORE_TAX ,b.DISCOUNT_BEFORE_TAX AS DISCOUNT ,b.TAX ,b.SHIPPING_PRICE ,b.TOTAL_SALES AS SELLING_PRICE ,UPPER(coalesce(c.order_status,d.order_status)) as OMS_order_status ,UPPER(coalesce(b.shipping_status, c.shipping_status,d.shipping_status)) AS SHIPPING_STATUS ,upper(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) FINAL_SHIPPING_STATUS ,cast(b.LINE_ITEM_ID as string) as SALEORDERITEMCODE ,d.sales_order_item_id as SALES_ORDER_ITEM_ID ,cast(coalesce(b.awb,c.awb,d.awb) as string) AWB ,UPPER(REPLACE(IF(ARRAY_LENGTH(GATEWAY) > 0, GATEWAY[OFFSET(0)],\'NA\'), \'\"\', \'\')) PAYMENT_GATEWAY ,upper(coalesce(c.payment_mode,d.payment_mode)) Payment_Mode ,Upper(coalesce(c.Courier,d.courier,b.courier)) AS COURIER ,coalesce(cast(timestamp(b.Shipping_created_at) as date),cast(timestamp(c.manifest_date) as date),cast(timestamp(d.dispatch_date) as date)) AS DISPATCH_DATE ,coalesce(cast(timestamp(c.delivered_date) as date),cast(timestamp(d.delivered_date) as date),case when b.shipping_status like \'delivered\' then cast(timestamp(b.shipping_status_update_date) as date) end) AS DELIVERED_DATE ,case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) AS RETURN_FLAG ,case when coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_quantity,0) end returned_quantity ,case when coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND, d.return_flag) = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_value,0) end returned_sales ,case when lower(b.order_status) in (\'cancelled\') then cast(quantity as INT64) end cancelled_quantity ,b.shopify_new_customer_flag as NEW_CUSTOMER_FLAG ,Upper(b.shopify_acquisition_product) as acquisition_product ,cast(case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) in (\'delivered\',\'delivered to origin\') then date_diff(date(b.ORDER_TIMESTAMP),date(coalesce(cast(b.shipping_status_update_date as timestamp),cast(c.shipping_last_update_date as timestamp), cast(d.shipping_last_update_date as timestamp))),day) when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status,d.shipping_status)) in (\'in transit\', \'shipment created\') then date_diff(date(b.ORDER_TIMESTAMP), CURRENT_DATE(),day) end as INT64) as Days_in_Shipment ,b.shopify_acquisition_date AS Marketplace_ACQUISITION_DATE ,b.SKU_CODE ,UPPER(b.PRODUCT_NAME_FINAL) PRODUCT_NAME_FINAL ,UPPER(b.PRODUCT_CATEGORY) PRODUCT_CATEGORY ,upper(b.PRODUCT_SUB_CATEGORY) PRODUCT_SUB_CATEGORY ,b.COLLECTION ,b.PRINT ,b.PRODUCT_TYPE ,b.category_code ,b.BAU_OFFLINE ,b.BAU_ONLINE ,b.FINAL_TAX_RATE ,b.SKU_CODE commonsku ,upper(coalesce(c.warehouse_name,d.warehouse_name)) WAREHOUSE ,coalesce(b.pincode,d.pincode,c.pincode) as pincode ,coalesce(c.pickup_pincode,fa.pincode) as source_pincode ,b.FINAL_MARKETPLACE ,b.MARKETPLACE_SEGMENTs as MARKETPLACE_SEGMENT ,b.TYPE_OF_SALE ,b.c