OF_SALE ,coalesce(b.child_category_code,b.category_code) as child_category_code FROM maplemonk.zouk_unicommerce_fact_items b left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from maplemonk.facility_pincode ) where rw = 1 ) fa on lower(b.warehouse_name) = lower(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM maplemonk.shipment_status_mapping ) ShipMap WHERE ShipMap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) WHERE NOT (LOWER(b.marketplace) LIKE ANY (\'%shopify%\') or LOWER(marketplace) LIKE ANY (\'%amazon%\',\'%blinkit%\', \'%gofynd\',\'zilo%\',\'%myntra_sor%\',\'myntra_sjit\',\'%flipkart sor%\',\'instamart%\',\'cocoblu_or\',\'cocoblu_gcc\',\'cocoblue_df%\',\'flipkart_sor%\',\'%zepto%\',\'%shopperstop%\',\'%shoppersstop%\',\'%crossword%\',\'%myntra_international_channel%\',\'%brands_unlimited%\',\'%emami%\',\'%chennai%\',\'%slikk%\') or LOWER(TYPE_OF_SALE) LIKE ANY (\'na\',\'%stock%\')) union all SELECT NULL AS customer_id ,\'AMAZON_VENDOR\' AS shop_name ,\'AMAZON_VENDOR\' AS marketplace ,\'AMAZON_VENDOR\' AS CHANNEL ,\'AMAZON_VENDOR\' AS SOURCE ,concat(asin, STARTDATE) ORDER_ID ,concat(asin, STARTDATE) reference_code ,null AS PHONE ,null AS NAME ,null AS EMAIL ,cast(cast(STARTDATE as date) as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,ASIN as SKU ,null PRODUCT_ID ,null AS PRODUCT_NAME ,\'IN\' CURRENCY ,NULL AS city ,NULL AS State ,NUll AS order_status ,cast(STARTDATE as date) AS Order_Date ,CAST(cast(STARTDATE as date) as datetime) ORDER_TIME ,cast(SHIPPEDUNITS AS FLOAT64) AS QUANTITY ,cast(JSON_EXTRACT_SCALAR(orderedRevenue,\'$.amount\') as float64)*1.12 AS gross_sales_before_tax ,cast(0 as float64) AS DISCOUNT ,cast(0 as float64) TAX ,cast(0 as float64) as SHIPPING_PRICE ,cast(JSON_EXTRACT_SC