E_OF_SALE ,\'BLINKIT\' AS marketplace from MapleMonk.zouk_db_Blinkit ) where lower(concat(cast(last_day(COALESCE(SAFE.PARSE_DATE(\'%d-%m-%Y\', Date),SAFE.PARSE_DATE(\'%d/%m/%Y\', Date))) as string),MARKETPLACE)) not in ( select distinct lower(concat(cast(last_day(order_date) as string),MARKETPLACE)) from maplemonk.s3_SKU_Level_Consolidated ) UNION ALL SELECT customer_id ,shop_name ,marketplace ,CHANNEL ,SOURCE ,ORDER_ID ,reference_code ,PHONE ,NAME ,EMAIL ,SHIPPING_LAST_UPDATE_DATE ,SKU ,PRODUCT_ID ,PRODUCT_NAME ,\'IN\' CURRENCY ,city ,State ,order_status , Order_Date , ORDER_TIME , QUANTITY , gross_sales_before_tax , DISCOUNT , TAX , SHIPPING_PRICE , SELLING_PRICE , OMS_ORDER_STATUS , SHIPPING_STATUS , FINAL_SHIPPING_STATUS ,SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID ,CAST(NULL AS STRING) AS AWB ,cast(payment_gateway as string) as payment_gateway , payment_mode , COURIER , DISPATCH_DATE ,delivered_date , DELIVERED_STATUS , RETURN_FLAG , returned_quantity , returned_sales , cancelled_quantity , NEW_CUSTOMER_FLAG , cast(ACQUISITION_PRODUCT as string) as ACQUISITION_PRODUCT , days_in_shipment ,null as ACQUISITION_DATE , sku_code , PRODUCT_NAME_FINAL , PRODUCT_CATEGORY , PRODUCT_SUB_CATEGORY , COLLECTION , PRINT , PRODUCT_TYPE , category_code , BAU_OFFLINE , BAU_ONLINE , FINAL_TAX_RATE , commonsku , warehouse , pincode , source_pincode ,FINAL_MARKETPLACE ,MARKETPLACE_SEGMENTs ,TYPE_OF_SALE ,category_code as child_category_code from maplemonk.s3_SKU_Level_Consolidated ; CREATE OR REPLACE TABLE maplemonk.second_Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM maplemonk.zouk_Secondary_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM maplemonk.zouk_Secondary_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE maplemonk.zouk_Secondary_sales_consolidated AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM maplemonk.zouk_Secondary_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM maplemonk.second_Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM maplemonk.second_Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email; ALTER TABLE maplemonk.zouk_Secondary_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE maplemonk.zouk_Secondary_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE maplemonk.zouk_Secondary_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM maplemonk.zouk_Secondary_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE maplemonk.zouk_Secondary_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE maplemonk.zouk_Secondary_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM maplemonk.zouk_Secondary_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE maplemonk.zouk_Secondary_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM maplemonk.zouk_Secondary_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE maplemonk.zouk_Secondary_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE maplemonk.zouk_Secondary_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM maplemonk.zouk_Secondary_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE maplemonk.zouk_Secondary_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final; Create or Replace Table maplemonk.zouk_Secondary_sales_consolidated as select sc.* ,case when DATE_DIFF(current_date(), sc1.first_order_date, DAY) < 180 then \'NPD\' else \'NON-NPD\' end as SKU_NPD_BUCKET ,case when DATE_DIFF(current_date(), scp.first_order_date, DAY) < 180 then \'NPD\' else \'NON-NPD\' end as CATEGORY_NPD_BUCKET ,case when DATE_DIFF(current_date(), scpr.first_order_date, DAY) < 180 then \'NPD\' else \'NON-NPD\' end as PRINT_NPD_BUCKET ,DATE_DIFF(current_date(), sc1.first_order_date, month) as SKU_AGE ,DATE_DIFF(current_date(), scp.first_order_date, Month) as CATEGORY_AGE ,DATE_DIFF(current_date(), scpr.first_order_date, Month) as PRINT_AGE ,DATE_DIFF(current_date(), sc1.first_order_date, Day) as SKU_AGE_DAYS from maplemonk.zouk_secondary_sales_consolidated sc left join ( select lower(coalesce(SKU_CODE,sku)) as sku ,min(order_date) first_order_date from maplemonk.zouk_secondary_sales_consolidated group by 1 )sc1 on lower(sc1.sku) = lower(coalesce(sc.SKU_CODE,sc.sku)) left join ( select lower(PRODUCT_CATEGORY) as PRODUCT_CATEGORY ,min(order_date) first_order_date from maplemonk.zouk_secondary_sales_consolidated group by 1 )scp on lower(scp.PRODUCT_CATEGORY) = lower((sc.PRODUCT_CATEGORY)) left join ( select lower(PRINT) as PRINT ,min(order_date) first_order_date from maplemonk.zouk_secondary_sales_consolidated group by 1 )scpr on lower(scpr.PRINT) = lower((sc.PRINT)) ;",
                    "transaction": true
                }
            ) }}
